<?php
namespace Tests\Feature;
use App\Models\ComplianceSetting; use App\Models\Employee; use App\Models\PayrollRun; use App\Models\Payslip; use App\Models\Tenant; use App\Services\JordanFilingReportService; use Illuminate\Support\Str; use Tests\TestCase;
class JordanFilingReportTest extends TestCase { public function test_locked_run_exports_tax_a2_and_ssc_evidence_fields():void{if(config('database.default')!=='mysql')$this->markTestSkipped('Requires MySQL.');$tenant=Tenant::create(['name'=>'Filing '.Str::random(4),'tax_number'=>'TAX123','ssc_establishment_number'=>'SSC123']);try{tenancy()->initialize($tenant);$setting=ComplianceSetting::create(['version_label'=>'file','effective_date'=>'2026-01-01','settings'=>[]]);$e=Employee::create(['name'=>'Ahmad Test','national_id'=>'N123','ssc_number'=>'S123','hire_date'=>'2026-01-01','salary'=>'500.000','status'=>'active']);$r=PayrollRun::create(['month'=>9,'year'=>2026,'status'=>'approved','compliance_setting_id'=>$setting->id,'locked_at'=>now()]);Payslip::create(['payroll_run_id'=>$r->id,'employee_id'=>$e->id,'gross_salary'=>'500.000','ssc_employee'=>'37.500','ssc_employer'=>'71.250','income_tax'=>'12.000','surcharge'=>'3.000','net_salary'=>'447.500','calculation_snapshot'=>['ssc_base'=>'500.000']]);$s=app(JordanFilingReportService::class);$tax=$s->taxA2Csv($r);$ssc=$s->sscCsv($r);$this->assertStringContainsString('employee_full_name',$tax);$this->assertStringContainsString('Ahmad Test',$tax);$this->assertStringContainsString('12.000',$tax);$this->assertStringContainsString('3.000',$tax);$this->assertStringContainsString('ssc_contribution_base_jod',$ssc);$this->assertStringContainsString('108.750',$ssc);}finally{if(tenancy()->initialized)tenancy()->end();$tenant->delete();}} }
